-- S-M04-01-ACTION-030（一括編集権限外在庫(030)）
-- 流す時点: 投入方法の「商品規格の登録時に、営業中の全店舗×在庫区分（EC-CUBE・スマレジ）の店舗別在庫が在庫0で自動作…」を終えたあと。手順書（S-M04-01-ACTION-030.md）の「DBへ直接設定する部分（SQL）」と同じ。
BEGIN;

-- [1] 文（投入方法）: NOAUTH-M0401-01-030の大阪支店・EC-CUBE以外の店舗別在庫は画面で削除できないためDBで直接削除する。
--     備考: 残す組(店舗・在庫区分)以外の、その商品コードの店舗別在庫だけを消す(ほかの商品の在庫は消さない)。店舗は店舗名で引き、残す店舗・残す在庫がそれぞれ1件に決まることを確かめる
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_base_info WHERE shop_name = '大阪支店') INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '残す店舗「大阪支店」が1件に決まらない（%件）', n; END IF; END $$;
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '商品コードNOAUTH-M0401-01-030が1件に決まらない（%件）', n; END IF; END $$;
DO $$ DECLARE n bigint; BEGIN SELECT (SELECT count(*) FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1) INTO n; IF n IS DISTINCT FROM 1 THEN RAISE EXCEPTION '残す在庫（商品コードNOAUTH-M0401-01-030・店舗大阪支店・在庫区分1）が1件に決まらない（%件）', n; END IF; END $$;
DELETE FROM dtb_inventory_plan_detail_edit_history WHERE inventory_plan_detail_id IN (SELECT id FROM dtb_inventory_plan_detail WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1))));
DELETE FROM dtb_inventory_plan_detail WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_edit_approval_detail WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_history WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_move_transfer_detail WHERE move_from_product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_move_transfer_detail WHERE move_to_product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_split_join_detail WHERE stock_split_join_id IN (SELECT id FROM dtb_stock_split_join WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1))));
DELETE FROM dtb_stock_split_join_status_history WHERE stock_split_join_id IN (SELECT id FROM dtb_stock_split_join WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1))));
DELETE FROM dtb_stock_split_join WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_stock_split_join_detail WHERE subject_product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_weekly_stock_history WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_weekly_stock_history_temp WHERE product_stock_id IN (SELECT id FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1)));
DELETE FROM dtb_product_stock WHERE product_class_id = (SELECT id FROM dtb_product_class WHERE product_code = 'NOAUTH-M0401-01-030') AND NOT ((base_info_id = (SELECT id FROM dtb_base_info WHERE shop_name = '大阪支店') AND stock_location_id = 1));

COMMIT;
